import { defineStore } from "pinia";
import { axiosInstance } from "@/plugins/axios";
import { handleError } from "@/helpers/errorHelper";

import {
  SHARED_FIELDS,
  categoryOfPlan,
  categoryFields,
  otherCategoryFields,
  planType,
} from "@/components/admin/license-manager/licenseHelpers";

const blankToNull = (value) => {
  if (value === undefined || value === null) return null;
  if (typeof value === "string") return value.trim() === "" ? null : value.trim();
  return value;
};

// Only the fields the API accepts on POST/PUT; the key is generated by the
// server and immutable, so it is never sent. The type always follows the
// plan; the other category's own fields are sent as null (the server clears
// them too).
const toApiPayload = (payload) => {
  const type = planType(payload.plan);
  const isTerm = type === "term";
  const isCustom = isTerm && payload.duration === "custom";
  const category = categoryOfPlan(payload.plan);

  const details = {};
  for (const field of [...SHARED_FIELDS, ...categoryFields(category)]) {
    details[field] = blankToNull(payload[field]);
  }
  for (const field of otherCategoryFields(category)) details[field] = null;
  if (details.member_count !== null) details.member_count = Number(details.member_count);

  return {
    // Fixed after create; the API accepts the same value on update.
    platform: payload.platform,
    plan: payload.plan,
    ...details,
    type,
    duration: isTerm ? payload.duration : null,
    expires_at: isCustom ? payload.expires_at || null : null,
    max_devices: Number(payload.max_devices),
    notes: payload.notes || null,
    is_active: !!payload.is_active,
  };
};

// Multipart body for products: booleans as 1/0 (Laravel's boolean rule),
// null as "" (the API turns it back into null), the icon as a File.
const toProductFormData = (payload) => {
  const form = new FormData();
  for (const [key, value] of Object.entries(payload)) {
    if (value === undefined) continue;
    if (value === null) form.append(key, "");
    if (typeof value === "boolean") form.append(key, value ? "1" : "0");
    else form.append(key, value);
  }
  return form;
};

// Indonesian regions, cached per list for the session.
const regionCache = new Map();
const REGION_PATHS = {
  province: () => "/regions/provinces",
  regency: (parent) => `/regions/provinces/${parent}/regencies`,
  district: (parent) => `/regions/regencies/${parent}/districts`,
  village: (parent) => `/regions/districts/${parent}/villages`,
};

export const useLicenseManagerStore = defineStore("licenseManager", {
  state: () => ({
    // Code of the product whose licenses the pages work on (from the URL).
    productCode: null,
    products: [],
    productsLoaded: false,
    productsLoading: false,
    overview: null,
    licenses: [],
    currentLicense: null,
    meta: {
      current_page: 1,
      last_page: 1,
      per_page: 10,
      total: 0,
      from: 0,
      to: 0,
    },
    summary: null,
    events: [],
    eventsMeta: { current_page: 1, last_page: 1, per_page: 15, total: 0, from: 0, to: 0 },
    eventsLoading: false,
    loading: false,
    error: null,
    success: null,
  }),

  getters: {
    // Admin license endpoints are nested under the product code.
    base: (state) => `/license-manager/products/${state.productCode}/licenses`,
    activeProducts: (state) => state.products.filter((p) => p.is_active),
    productByCode: (state) => (code) => state.products.find((p) => p.code === code) || null,
  },

  actions: {
    /* =============================
     * PRODUCT CONTEXT
     * ============================= */
    setProduct(code) {
      if (this.productCode !== code) {
        this.productCode = code;
        this.licenses = [];
        this.summary = null;
        this.currentLicense = null;
        this.events = [];
      }
    },

    /* =============================
     * PRODUCTS
     * ============================= */
    async fetchProducts({ force = false } = {}) {
      if (this.productsLoaded && !force) return this.products;
      this.productsLoading = true;
      try {
        const { data } = await axiosInstance.get("/license-manager/products");
        this.products = data.data ?? [];
        this.productsLoaded = true;
        return this.products;
      } catch (e) {
        this.error = handleError(e);
        throw e;
      } finally {
        this.productsLoading = false;
      }
    },

    async createProduct(payload) {
      const { data } = await axiosInstance.post("/license-manager/products", toProductFormData(payload));
      this.products = [...this.products, data.data];
      return data.data;
    },

    // An icon upload goes as multipart POST with _method=PUT (the
    // codebase's pattern for file uploads on update).
    async updateProduct(code, payload) {
      const { data } = payload.icon instanceof File
        ? await axiosInstance.post(`/license-manager/products/${code}`, toProductFormData({ ...payload, _method: "PUT" }))
        : await axiosInstance.put(`/license-manager/products/${code}`, payload);
      this.products = this.products.map((p) => (p.code === code ? data.data : p));
      return data.data;
    },

    async deleteProduct(code) {
      await axiosInstance.delete(`/license-manager/products/${code}`);
      this.products = this.products.filter((p) => p.code !== code);
    },

    /* =============================
     * OVERVIEW (all products)
     * ============================= */
    async fetchOverview() {
      const { data } = await axiosInstance.get("/license-manager/summary");
      this.overview = data.data;
      return data.data;
    },

    // Overview panels (all products). Errors are left to the caller, which
    // shows a quiet "not available" state instead of a toast.
    async fetchExpiring({ days = 30, limit = 10 } = {}) {
      const { data } = await axiosInstance.get("/license-manager/expiring", { params: { days, limit } });
      return data.data?.data ?? data.data ?? [];
    },

    async fetchRecentEvents({ limit = 15 } = {}) {
      const { data } = await axiosInstance.get("/license-manager/events/recent", { params: { limit } });
      return data.data?.data ?? data.data ?? [];
    },

    /* =============================
     * GET PAGINATED
     * ============================= */
    async fetchLicensesPaginated(params = {}) {
      this.loading = true;
      this.error = null;

      try {
        const perPage = params.per_page || 10;
        const { data } = await axiosInstance.get(`${this.base}/all/paginated`, {
          params: {
            search: params.search || "",
            status: params.status || undefined,
            type: params.type || undefined,
            plan: params.plan || undefined,
            platform: params.platform || undefined,
            sort_by: params.sort_by || undefined,
            sort_dir: params.sort_dir || undefined,
            page: params.page || 1,
            // Other paginated modules use row_per_page; send both so either
            // backend convention is honoured.
            per_page: perPage,
            row_per_page: perPage,
          },
        });

        if (data.data?.data) {
          this.licenses = data.data.data;
          this.meta = data.data.meta ?? this.meta;
        } else if (Array.isArray(data.data)) {
          this.licenses = data.data;
        } else {
          this.licenses = [];
        }
      } catch (e) {
        this.error = handleError(e);
      } finally {
        this.loading = false;
      }
    },

    /* =============================
     * SUMMARY (dashboard cards)
     * ============================= */
    async fetchSummary() {
      try {
        const { data } = await axiosInstance.get(`${this.base}/summary`);
        this.summary = data.data;
        return data.data;
      } catch (e) {
        // The cards are optional; the table still works without them.
        this.summary = null;
        return null;
      }
    },

    /* =============================
     * TRACKING EVENTS
     * ============================= */
    async fetchEvents(id, params = {}) {
      this.eventsLoading = true;
      try {
        const perPage = params.per_page || 15;
        const { data } = await axiosInstance.get(`${this.base}/${id}/events`, {
          params: {
            event: params.event || undefined,
            page: params.page || 1,
            per_page: perPage,
            row_per_page: perPage,
          },
        });
        this.events = data.data?.data ?? [];
        this.eventsMeta = data.data?.meta ?? this.eventsMeta;
        return this.events;
      } catch (e) {
        this.error = handleError(e);
        throw e;
      } finally {
        this.eventsLoading = false;
      }
    },

    /* =============================
     * SWITCH ON / OFF (partial update)
     * ============================= */
    async setActive(id, isActive) {
      this.error = null;

      try {
        const { data } = await axiosInstance.put(`${this.base}/${id}`, { is_active: !!isActive });
        const updated = data.data;

        if (updated) {
          const index = this.licenses.findIndex((l) => l.id === id);
          if (index !== -1) this.licenses[index] = { ...this.licenses[index], ...updated };
          if (this.currentLicense?.id === id) {
            this.currentLicense = { ...this.currentLicense, ...updated, activations: this.currentLicense.activations };
          }
        }

        return updated;
      } catch (e) {
        this.error = handleError(e);
        throw e;
      }
    },

    /* =============================
     * GET BY ID
     * ============================= */
    async fetchLicense(id) {
      try {
        const { data } = await axiosInstance.get(`${this.base}/${id}`);
        this.currentLicense = data.data;
        return data.data;
      } catch (e) {
        this.error = handleError(e);
        throw e;
      }
    },

    /* =============================
     * CREATE
     * ============================= */
    async createLicense(payload) {
      this.error = null;

      try {
        const { data } = await axiosInstance.post(this.base, toApiPayload(payload));
        this.currentLicense = data.data;
        return data.data;
      } catch (e) {
        this.error = handleError(e);
        throw e;
      }
    },

    /* =============================
     * UPDATE
     * ============================= */
    async updateLicense(id, payload) {
      this.error = null;

      try {
        const { data } = await axiosInstance.put(`${this.base}/${id}`, toApiPayload(payload));
        const updated = data.data;

        if (updated) {
          const index = this.licenses.findIndex((l) => l.id === id);
          if (index !== -1) {
            this.licenses[index] = { ...this.licenses[index], ...updated };
          }
          if (this.currentLicense?.id === id) {
            this.currentLicense = { ...this.currentLicense, ...updated };
          }
        }

        return updated;
      } catch (e) {
        this.error = handleError(e);
        throw e;
      }
    },

    /* =============================
     * DELETE
     * ============================= */
    async deleteLicense(id) {
      try {
        await axiosInstance.delete(`${this.base}/${id}`);
        this.licenses = this.licenses.filter((l) => l.id !== id);

        if (this.currentLicense?.id === id) {
          this.currentLicense = null;
        }
      } catch (e) {
        this.error = handleError(e);
        throw e;
      }
    },

    /* =============================
     * RELEASE DEVICE (delete activation)
     * ============================= */
    async releaseActivation(licenseId, activationId) {
      try {
        await axiosInstance.delete(`${this.base}/${licenseId}/activations/${activationId}`);

        if (this.currentLicense?.id === licenseId) {
          const activations = (this.currentLicense.activations || []).filter(
            (a) => a.id !== activationId
          );
          this.currentLicense = {
            ...this.currentLicense,
            activations,
            devices_used: activations.length,
          };
        }
      } catch (e) {
        this.error = handleError(e);
        throw e;
      }
    },

    /* =============================
     * INDONESIAN REGIONS: [{code, name}] sorted by name
     * ============================= */
    async fetchRegions(level, parentCode = null) {
      const key = `${level}:${parentCode ?? ""}`;
      if (!regionCache.has(key)) {
        const request = axiosInstance
          .get(REGION_PATHS[level](parentCode))
          .then(({ data }) => data.data ?? [])
          .catch((e) => {
            regionCache.delete(key);
            throw e;
          });
        regionCache.set(key, request);
      }
      return regionCache.get(key);
    },

    /* =============================
     * CERTIFICATE PDF (blob download, keeps the Bearer token)
     * ============================= */
    async downloadCertificate(id, fallbackName = "License.pdf") {
      const response = await axiosInstance.get(`${this.base}/${id}/certificate`, { responseType: "blob" });
      const disposition = response.headers?.["content-disposition"] || "";
      const match = /filename="?([^";]+)"?/i.exec(disposition);
      const url = URL.createObjectURL(new Blob([response.data], { type: "application/pdf" }));
      const link = document.createElement("a");
      link.href = url;
      link.download = match?.[1] || fallbackName;
      document.body.appendChild(link);
      link.click();
      link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 10000);
    },

    clearMessages() {
      this.error = null;
      this.success = null;
    },

    clearState() {
      this.productCode = null;
      this.licenses = [];
      this.currentLicense = null;
      this.summary = null;
      this.events = [];
      this.error = null;
      this.success = null;
    },
  },
});
